package org.rabochaya.projects;
import java.util.*;import java.util.regex.*;
/** WGS84-only local conversions. No location, network, Android or user-data APIs.
 * Krueger series through n^6; references and supported bounds in COORDINATES.md.
 */
public final class Coordinates {
 public static final int DD=0,DM=1,DMS=2,UTM=3,MGRS=4;
 private static final String[] NAMES={"WGS 84 · градусы","WGS 84 · градусы и минуты","WGS 84 · градусы, минуты, секунды","UTM · WGS 84","MGRS · WGS 84"};
 private static final String BANDS="CDEFGHJKLMNPQRSTUVWX",ROWS="ABCDEFGHJKLMNPQRSTUV";
 private static final String[] COLS={"ABCDEFGH","JKLMNPQR","STUVWXYZ"};
 private static final double A=6378137,F=1/298.257223563,E=Math.sqrt(F*(2-F)),K=.9996,N=F/(2-F);
 private static final double N2=N*N,N3=N2*N,N4=N3*N,N5=N4*N,N6=N5*N;
 private static final double SCALE=K*A/(1+N)*(1+N2/4+N4/64+N6/256);
 private static final double[] ALPHA={0,N/2-2*N2/3+5*N3/16+41*N4/180-127*N5/288+7891*N6/37800,13*N2/48-3*N3/5+557*N4/1440+281*N5/630-1983433*N6/1935360,61*N3/240-103*N4/140+15061*N5/26880+167603*N6/181440,49561*N4/161280-179*N5/168+6601661*N6/7257600,34729*N5/80640-3418889*N6/1995840,212378941*N6/319334400};
 private static final double[] BETA={0,N/2-2*N2/3+37*N3/96-N4/360-81*N5/512+96199*N6/604800,N2/48+N3/15-437*N4/1440+46*N5/105-1118711*N6/3870720,17*N3/480-37*N4/840-209*N5/4480+5569*N6/90720,4397*N4/161280-11*N5/504-830251*N6/7257600,4583*N5/161280-108847*N6/3991680,20648693*N6/638668800};
 private Coordinates(){}
 public static String[] names(){return NAMES.clone();}
 public static String name(int format){checkFormat(format);return NAMES[format];}
 public static final class Position {public final double lat,lon;public Position(double lat,double lon){geographic(lat,lon);this.lat=lat;this.lon=lon;}}
 public static final class Grid {public final int zone;public final boolean north;public final double easting,northing;public Grid(int z,boolean n,double e,double y){if(z<1||z>60||!finite(e)||!finite(y)||e<100000||e>=900000||y<0||y>10000000)throw bad("Некорректная зона или координаты UTM");zone=z;north=n;easting=e;northing=y;}}
 private static boolean finite(double value){return !Double.isNaN(value)&&!Double.isInfinite(value);}
 private static IllegalArgumentException bad(String text){return new IllegalArgumentException(text);}
 private static void checkFormat(int format){if(format<DD||format>MGRS)throw bad("Неизвестный формат координат");}
 private static void geographic(double lat,double lon){if(!finite(lat)||!finite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw bad("Широта: от −90 до 90; долгота: от −180 до 180");}
 private static void utmLatitude(double lat){if(lat< -80||lat>=84)throw bad("UTM/MGRS: широта от −80 до 84°; полярная UPS ещё не поддерживается");}
 public static int zone(double lat,double lon){geographic(lat,lon);utmLatitude(lat);int z=Math.min(60,(int)Math.floor((lon+180)/6)+1);if(lat>=56&&lat<64&&lon>=3&&lon<12)z=32;if(lat>=72&&lon>=0&&lon<42)z=lon<9?31:lon<21?33:lon<33?35:37;return z;}
 private static double asinh(double x){return Math.copySign(Math.log(Math.abs(x)+Math.hypot(1,x)),x);}
 private static double atanh(double x){return .5*Math.log((1+x)/(1-x));}
 private static double delta(double degrees){double d=degrees%360;return d>180?d-360:d< -180?d+360:d;}
 public static Grid toUtm(double lat,double lon){int z=zone(lat,lon);double[] xy=forward(lat,delta(lon-(z*6-183)));return new Grid(z,lat>=0,xy[0]+500000,xy[1]+(lat<0?10000000:0));}
 private static double[] forward(double lat,double dlon){double phi=Math.toRadians(lat),lambda=Math.toRadians(dlon),tau=Math.tan(phi),sigma=Math.sinh(E*atanh(E*tau/Math.hypot(1,tau))),tp=tau*Math.hypot(1,sigma)-sigma*Math.hypot(1,tau);double xi0=Math.atan2(tp,Math.cos(lambda)),eta0=asinh(Math.sin(lambda)/Math.hypot(tp,Math.cos(lambda))),xi=xi0,eta=eta0;for(int j=1;j<=6;j++){xi+=ALPHA[j]*Math.sin(2*j*xi0)*Math.cosh(2*j*eta0);eta+=ALPHA[j]*Math.cos(2*j*xi0)*Math.sinh(2*j*eta0);}return new double[]{SCALE*eta,SCALE*xi};}
 public static Position fromUtm(Grid grid){Position p=inverse(grid.zone,grid.north,grid.easting,grid.northing);if(p.lat< -80-1e-8||p.lat>=84+1e-8)throw bad("Координаты вне области UTM");return p;}
 private static Position inverse(int zone,boolean north,double easting,double northing){double eta=(easting-500000)/SCALE,xi=(northing-(north?0:10000000))/SCALE,eta0=eta,xi0=xi;for(int j=1;j<=6;j++){xi0-=BETA[j]*Math.sin(2*j*xi)*Math.cosh(2*j*eta);eta0-=BETA[j]*Math.cos(2*j*xi)*Math.sinh(2*j*eta);}double sh=Math.sinh(eta0),co=Math.cos(xi0),tp=Math.sin(xi0)/Math.hypot(sh,co),tau=tp;for(int i=0;i<10;i++){double sigma=Math.sinh(E*atanh(E*tau/Math.hypot(1,tau))),estimate=tau*Math.hypot(1,sigma)-sigma*Math.hypot(1,tau);double step=(tp-estimate)/Math.hypot(1,estimate)*(1+(1-E*E)*tau*tau)/((1-E*E)*Math.hypot(1,tau));tau+=step;if(Math.abs(step)<1e-13*Math.max(1,Math.abs(tau)))break;}return new Position(Math.toDegrees(Math.atan(tau)),delta(zone*6-183+Math.toDegrees(Math.atan2(sh,co))));}
 public static String mgrs(double lat,double lon,int precision){if(precision<1||precision>5)throw bad("Уточнение MGRS: от 1 до 5 цифр");Grid g=toUtm(lat,lon);char band=BANDS.charAt(Math.min(19,(int)Math.floor((lat+80)/8)));int column=(int)Math.floor(g.easting/100000)-1,row=(int)Math.floor(g.northing/100000)%20;if(column<0||column>=8)throw bad("Квадрат вне области MGRS");char col=COLS[(g.zone-1)%3].charAt(column),r=ROWS.charAt((row+(g.zone%2==0?5:0))%20);int unit=(int)Math.pow(10,5-precision),east=((int)Math.floor(g.easting)%100000)/unit,north=((int)Math.floor(g.northing)%100000)/unit;return String.format(Locale.US,"%02d%c %c%c %0"+precision+"d %0"+precision+"d",g.zone,band,col,r,east,north);}
 public static Position fromMgrs(String text){String value=clean(text).toUpperCase(Locale.ROOT).replaceAll("\\s+","");Matcher m=Pattern.compile("^(\\d{1,2})([C-HJ-NP-X])([A-HJ-NP-Z])([A-HJ-NP-V])(\\d{2,10})$").matcher(value);if(!m.matches()||m.group(5).length()%2!=0)throw bad("MGRS: зона, пояс, квадрат и от 1 до 5 цифр E/N");int z=Integer.parseInt(m.group(1));if(z<1||z>60)throw bad("Зона MGRS: от 1 до 60");char band=m.group(2).charAt(0);if(band=='X'&&(z==32||z==34||z==36))throw bad("Зона MGRS не существует в поясе X");int bi=BANDS.indexOf(band),column=COLS[(z-1)%3].indexOf(m.group(3)),row=ROWS.indexOf(m.group(4));if(column<0||row<0)throw bad("Квадрат не соответствует зоне MGRS");row=(row-(z%2==0?5:0)+20)%20;int digits=m.group(5).length()/2;double unit=Math.pow(10,5-digits),east=(column+1)*100000+Integer.parseInt(m.group(5).substring(0,digits))*unit,north=row*100000+Integer.parseInt(m.group(5).substring(digits))*unit;double lower=-80+8*bi,upper=bi==19?84:lower+8;boolean nh=band>='N';double minNorth=Math.floor((forward(lower,0)[1]+(nh?0:10000000))/100000)*100000;while(north<minNorth)north+=2000000;if(north+unit>10000000+1e-8)throw bad("Квадрат вне пояса MGRS");Position center=inverse(z,nh,east+unit/2,north+unit/2);double minLat=90,maxLat=-90,minLon=1000,maxLon=-1000;for(double x:new double[]{east,east+unit,Math.max(east,Math.min(east+unit,500000))})for(double y:new double[]{north,north+unit}){Position p=inverse(z,nh,x,y);minLat=Math.min(minLat,p.lat);maxLat=Math.max(maxLat,p.lat);double longitude=z*6-183+delta(p.lon-(z*6-183));minLon=Math.min(minLon,longitude);maxLon=Math.max(maxLon,longitude);}if(maxLat<lower-1e-8||minLat>upper+1e-8)throw bad("Квадрат не соответствует широтному поясу MGRS");double west=z*6-186,eastBound=west+6;if(band=='V'){if(z==31)eastBound=3;else if(z==32)west=3;}if(band=='X'){if(z==31)eastBound=9;else if(z==33){west=9;eastBound=21;}else if(z==35){west=21;eastBound=33;}else if(z==37){west=33;eastBound=42;}}if(maxLon<west-1e-8||minLon>eastBound+1e-8)throw bad("Квадрат вне долготной зоны MGRS");return center;}
 public static String format(double lat,double lon,int format){geographic(lat,lon);checkFormat(format);if(format==DD)return String.format(Locale.US,"%.6f, %.6f",lat,lon);if(format==DM||format==DMS)return angle(lat,true,format)+"; "+angle(lon,false,format);if(format==MGRS)return mgrs(lat,lon,5);Grid g=toUtm(lat,lon);return String.format(Locale.US,"%02d %s %.3f %.3f",g.zone,g.north?"N":"S",g.easting,g.northing);}
 private static String angle(double value,boolean latitude,int format){boolean negative=Double.doubleToRawLongBits(value)<0;char hemi=latitude?(negative?'S':'N'):(negative?'W':'E');long ticks=Math.round(Math.abs(value)*(format==DM?600000:360000));int degrees=(int)(ticks/(format==DM?600000:360000));long rest=ticks%(format==DM?600000:360000);if(format==DM)return String.format(Locale.US,"%d°%07.4f′ %c",degrees,rest/10000.0,hemi);return String.format(Locale.US,"%d°%02d′%05.2f″ %c",degrees,rest/6000,rest%6000/100.0,hemi);}
 private static String clean(String text){if(text==null||text.length()>512)throw bad("Введите координаты (до 512 символов)");return text.trim().replace('−','-');}
 private static double number(String text){if(!text.matches("[+-]?(?:\\d+(?:[.,]\\d*)?|[.,]\\d+)(?:[eE][+-]?\\d+)?"))throw bad("Ожидается десятичное число");try{double value=Double.parseDouble(text.replace(',','.'));if(!finite(value))throw bad("Координаты должны быть конечными числами");return value;}catch(NumberFormatException e){throw bad("Не удалось прочитать число: "+text);}}
 public static Position parse(String text,int format){checkFormat(format);String value=clean(text);if(format==MGRS)return fromMgrs(value);if(format==UTM){Matcher m=Pattern.compile("^(\\d{1,2})\\s*([NSns])\\s+([^\\s]+)\\s+([^\\s]+)$").matcher(value);if(!m.matches())throw bad("UTM: зона, полушарие N/S, Easting, Northing; пример: 37 N 410000 6170000");return fromUtm(new Grid(Integer.parseInt(m.group(1)),m.group(2).equalsIgnoreCase("N"),number(m.group(3)),number(m.group(4))));}if(format==DD){String[] parts=value.replaceAll(",\\s+"," ").trim().split("[;\\s]+");if(parts.length!=2)throw bad("Введите широту и долготу через пробел");return new Position(number(parts[0]),number(parts[1]));}String[] parts=value.split("[;\\n]+");if(parts.length!=2)throw bad("Широта и долгота — отдельными строками или через точку с запятой");return new Position(parseAngle(parts[0],true,format),parseAngle(parts[1],false,format));}
 private static double parseAngle(String text,boolean lat,int format){String s=text.trim().toUpperCase(Locale.ROOT);Matcher h=Pattern.compile("[NSEWСЮВЗ]").matcher(s);char hemi=0;int start=-1;while(h.find()){if(hemi!=0)throw bad("Один указатель полушария на координату");hemi=h.group().charAt(0);start=h.start();}if(hemi!=0){if(start!=0&&start!=s.length()-1)throw bad("Полушарие укажите перед или после координаты");s=s.substring(0,start)+s.substring(start+1);if(lat&&"NSСЮ".indexOf(hemi)<0||!lat&&"EWВЗ".indexOf(hemi)<0)throw bad("Неверное полушарие для широты/долготы");}s=s.trim();boolean neg=s.startsWith("-");if(hemi!=0&&(neg||s.startsWith("+")))throw bad("Используйте знак либо букву полушария");s=s.replaceAll("[°º′’'″\"“”]"," ").trim();String[] p=s.split("\\s+");int count=format==DM?2:3;if(p.length!=count)throw bad(format==DM?"Нужны градусы и минуты":"Нужны градусы, минуты и секунды");double d=number(p[0]),minutes=number(p[1]),seconds=count==3?number(p[2]):0;if(Math.abs(d)!=Math.floor(Math.abs(d))||minutes<0||minutes>=60||seconds<0||seconds>=60||count==3&&minutes!=Math.floor(minutes))throw bad("Градусы целые; минуты/секунды от 0 до 60");double absolute=Math.abs(d)+minutes/60+seconds/3600;if(absolute>(lat?90:180))throw bad("Координата вне допустимого диапазона");boolean south=hemi=='S'||hemi=='W'||hemi=='Ю'||hemi=='З';return (neg||south?-1:1)*absolute;}
}
